import{_ as a,o as s,c as d,a2 as i}from"./chunks/framework.D66Xq0Kv.js";const E=JSON.parse('{"title":"BERT 微调","description":"","frontmatter":{},"headers":[],"relativePath":"LLM训练/BERT微调.md","filePath":"LLM训练/BERT微调.md","lastUpdated":null}'),e={name:"LLM训练/BERT微调.md"};function n(p,t,l,r,o,h){return s(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="bert-微调" tabindex="-1">BERT 微调 <a class="header-anchor" href="#bert-微调" aria-label="Permalink to &quot;BERT 微调&quot;">​</a></h1><p>短文本要落到事先定好的几类表情。编码器加上一个分类头，用交叉熵把句子训到类别上，输出就锁在这几类里。生成式模型更重，也不容易把回答收成固定标签。</p><p>下面以中文短回复、八类表情为例：害怕、生气、疑惑、愉悦、无、悲伤、害羞、惊喜。换一套固定类别时，口径、划分和选点指标照同一套做。</p><h2 id="先把口径写死" tabindex="-1">先把口径写死 <a class="header-anchor" href="#先把口径写死" aria-label="Permalink to &quot;先把口径写死&quot;">​</a></h2><p>标注看的是说话人此刻该摆出的脸。句子里出现「伤心」「紧张」，并不自动落入对应的类。</p><table tabindex="0"><thead><tr><th>类</th><th>标</th><th>不标</th></tr></thead><tbody><tr><td>害怕</td><td>惊吓、恐惧、危险，上台或见人之前的发怵</td><td>运维式「先暂停操作」；单纯害羞时的紧张</td></tr><tr><td>生气</td><td>指责、发火、被冒犯、威胁式警告</td><td>翻白眼、阴阳怪气、懒得理</td></tr><tr><td>疑惑</td><td>没听懂、前后矛盾、真在发问</td><td>语气平静的事务询问</td></tr><tr><td>愉悦</td><td>开心、寒暄示好、满足、邀约时的高兴</td><td>惊喜的「没想到」；被夸之后的羞</td></tr><tr><td>无</td><td>通知和指引、安抚对方、出糗尴尬、嘲讽白眼</td><td>明显的喜怒哀惧</td></tr><tr><td>悲伤</td><td>失落、想念、抑郁、心疼自己</td><td>惊吓；生闷气</td></tr><tr><td>害羞</td><td>被注视、被夸、表白、初见时的羞赧</td><td>纯开心；纯害怕</td></tr><tr><td>惊喜</td><td>意外、没想到、哇居然</td><td>计划内的高兴；惊吓</td></tr></tbody></table><p>「无」内部还可以再看四种情况，用来分析错例：通知（会议室在三楼）、安抚（别想太多）、尴尬（发错群）、嘲讽（行了吧、画大饼）。这四种子型留在分析里。模型的输出维仍然是上面八类：没有尴尬脸和翻白眼可摆，安抚对方时脸保持平静。生气和嘲讽的分界是发火、威胁归生气，不耐烦、阴阳怪气归无。</p><p>几组容易混的句子写进口径，标注和补数据都按这个分：</p><ul><li>「好紧张」：上台、危险归害怕；被喜欢的人注视归害羞。</li><li>「你怎么能这样，我真的很伤心」归悲伤。</li><li>「这个功能怎么用」：平静请教归无；明显转不过弯、对不上归疑惑。</li><li>「居然 / 没想到 / 哇」：意外本身归惊喜；计划内的高兴归愉悦；惊吓归害怕；没听懂归疑惑。</li><li>离开、空、不在、群变安静归悲伤。夜里、门口这些场景词单独出现，仍按这句话在说什么标。</li></ul><p>类别顺序在三处保持一致：配置里的类别列表、标签表里的 id、数据文件里的标签字段。训练开始时核对配置和标签表，不一致就停。数据里用稳定的英文 id（<code>afraid</code>、<code>angry</code> 等），展示时再用中文名。增删类别时，配置、标签表、数据、冻结的评测集一起改。</p><h2 id="数据怎么来" tabindex="-1">数据怎么来 <a class="header-anchor" href="#数据怎么来" aria-label="Permalink to &quot;数据怎么来&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;已有语料&quot;] --&gt; C[&quot;按口径清洗&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B[&quot;混淆类的场景补句&quot;] --&gt; C</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[&quot;去重并丢掉冲突标签&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E[&quot;排除冻结评测集的原文&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; F[&quot;按类存放的训练集&quot;]</span></span></code></pre></div><p>从已有语料出发，先按口径拿掉标错的句子。典型的一批是操作指令被标成害怕：「先暂停操作」「先确认风险」说的是步骤。拿掉之后，只给仍然混淆的类补真实场景句，例如害怕、害羞、无。已经分开的类不必为了凑条数再平均加水。</p><p>一条样本一行：文本加类别 id。读入时丢掉空文本、未知标签、短于两个字的句子。同一句话出现两次且标签相同，留一条；两条标签互相冲突，都丢掉，避免监督自相矛盾。</p><p>评测用的手工句子事先冻结。合成训练集时排除这些原文，也排除用来探盲区的扩充句，避免同一句话既出现在训练里又出现在考试里。</p><p>划分用分层抽样，大约 8:1:1，种子固定，两次实验才能对齐。这份测试集和训练来自同一堆句子，只能看出模型有没有记住这堆分布。换数据、换参数、换骨干时，对比同一份冻结的手工集。手工集要改，单独立项，否则前后分数没法比。划分测试到了九成、手工集停在七成上下，说明训练句彼此太像，上线观感以手工集为准。</p><h2 id="模型" tabindex="-1">模型 <a class="header-anchor" href="#模型" aria-label="Permalink to &quot;模型&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    T[&quot;短文本&quot;] --&gt; K[&quot;分词&lt;br/&gt;补齐或截断到固定长度&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    K --&gt; Enc[&quot;BERT 编码器&lt;br/&gt;12 层 · 隐层 768&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Enc --&gt; Cls[&quot;取 CLS&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    Cls --&gt; Head[&quot;Dropout → Linear → logits&quot;]</span></span></code></pre></div><p>参数大约一亿，几乎都在编码器里。取编码器的 pooler 输出；没有 pooler 就用最后一层第一个位置。分类头是一层线性变换，权重用标准差 0.02 的正态初始化，偏置为 0。前向直接返回 logits。交叉熵打在 logits 上；softmax、取最大类、低置信时改成兜底类，都留在推理。</p><p>数据很少时可以冻住编码器，只训分类头，先确认这批句子和标签能分开。句子够了就全参微调。全参微调的学习率用 <code>2e-5</code> 这一档，比从头训练小很多，避免把预训练的中文表示冲掉。若接着一次冻住编码器的权重继续训，要把编码器解开。</p><p>隐层宽度从预训练配置读取。换骨干就要重新训练，分词和下游使用的固定长度一起换。</p><p>分数上不去时，先核对口径和训练句是不是同一套分布。层数、多头、把上一句历史拼进来，解决不了标签和场景没对齐的问题。</p><h2 id="参数各自决定什么" tabindex="-1">参数各自决定什么 <a class="header-anchor" href="#参数各自决定什么" aria-label="Permalink to &quot;参数各自决定什么&quot;">​</a></h2><p>超参、路径、阈值写在同一份配置里。对比实验只改这一份，种子保持不变。</p><table tabindex="0"><thead><tr><th>参数</th><th>这一档任务上的取值</th><th>决定什么</th></tr></thead><tbody><tr><td>学习率</td><td><code>2e-5</code></td><td>AdamW 的峰值。全参微调 BERT 常用这个量级；再大，预训练特征容易被冲掉</td></tr><tr><td>batch</td><td>16</td><td>显存不够再降。batch 一变，每个 epoch 的 step 数就变，warmup 的步数跟着变</td></tr><tr><td>epoch 上限</td><td>25</td><td>循环最多跑这么多轮。真正停靠早停，很少跑满</td></tr><tr><td>warmup 比例</td><td>0.1</td><td>总 step 的一成用来把学习率从 0 升到峰值，之后线性降到 0。每个 batch 更新一次</td></tr><tr><td>权重衰减</td><td>0.01</td><td>抑制权重过大</td></tr><tr><td>梯度裁剪</td><td>1.0</td><td>单步更新的幅度上限</td></tr><tr><td>早停耐心</td><td>3</td><td>验证 Macro F1 连续 3 个 epoch 没有超过历史最佳就停，并加载最佳权重</td></tr><tr><td>标签平滑</td><td>0.1</td><td>正确类大约留 0.9，其余类分掉 0.1。减轻「分错了仍然给出接近 1 的概率」</td></tr><tr><td>类别权重</td><td>关</td><td>打开后按训练集频数的反比加权。少类极少时有用；少类一旦被灌得很多，权重会压过其它类</td></tr><tr><td>序列长度</td><td>128</td><td>短句补齐，超长截断。单条回复通常远短于 128。下游要固定形状时，训完再改长度就要重新导出</td></tr></tbody></table><p>选模型的指标是验证集 Macro F1。类别一旦不均衡，准确率会被大类撑住，checkpoint 里可以记下准确率，比较时以 F1 为准。</p><p>推理可以设置信度阈值：最大概率低于阈值就改成兜底类「无」。阈值放在 0.35 时，不少错例的概率仍然高于 0.9，阈值碰不到它们。先把标签平滑和数据做好，再考虑把阈值抬高。</p><h2 id="一个-step-在做什么" tabindex="-1">一个 step 在做什么 <a class="header-anchor" href="#一个-step-在做什么" aria-label="Permalink to &quot;一个 step 在做什么&quot;">​</a></h2><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">flowchart LR</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    A[&quot;一批句子&quot;] --&gt; B[&quot;编码器 + 分类头&lt;br/&gt;logits&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    B --&gt; C[&quot;交叉熵&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    C --&gt; D[&quot;反传并裁剪梯度&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    D --&gt; E[&quot;AdamW 更新&quot;]</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    E --&gt; F[&quot;学习率按 step 升降&quot;]</span></span></code></pre></div><p>训练模式下累计的准确率到后期会接近满分，它说明这批句子被拟合了。验证时关掉 Dropout、停掉梯度，留下全部预测，用来算 Macro F1 和混淆矩阵。验证 F1 超过历史最佳才覆盖最佳权重；每一轮的权重可以另存，方便回看是从哪一轮开始变差的。跑完后用最佳权重量一遍划分出来的测试集，看分类报告。这个数和冻结手工集分开读。</p><p>一轮迭代是：改口径或补句子，重新合成训练集并继续排除金标原文，再训练，最后在同一份冻结集上对比。</p>`,31)])])}const u=a(e,[["render",n]]);export{E as __pageData,u as default};
